package compiler

import (
	"bytes"
	"fmt"
	"go/ast"
	goparser "go/parser"
	goprinter "go/printer"
	"go/token"
	"go/types"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
)

// Generate generates Go source for every .gx file under root. The result maps
// each generated file path to its source. It returns diagnostics instead when
// any check fails.
func Generate(root string) (map[string][]byte, []Diagnostic) {
	files, diags, _, _, _ := generate(root, nil)
	return files, diags
}

// generate is Generate with the analysis pieces returned, for the
// incremental Session (NFR-05). overlay holds in-memory input files
// (REQ-DEV-08).
func generate(root string, overlay map[string][]byte) (map[string][]byte, []Diagnostic, *typesResult, *loader, []string) {
	root = absoluteRoot(root)
	l := newLoader()
	l.overlay = overlay
	dirs := collectDirs(root)
	var diags []Diagnostic
	for _, dir := range dirs {
		diags = append(diags, l.checkDir(dir)...)
	}
	res, tdiags := l.analyze(root, dirs)
	diags = append(diags, tdiags...)
	if len(diags) > 0 {
		sortDiags(diags)
		return nil, diags, res, l, dirs
	}
	out := map[string][]byte{}
	for _, dir := range dirs {
		p := l.load(dir)
		for base, f := range p.Files {
			src, gdiags := generateFile(l, p, base, f, res)
			if len(gdiags) > 0 {
				diags = append(diags, gdiags...)
				continue
			}
			out[filepath.Join(dir, base+"_gx.go")] = src
		}
	}
	for path, src := range res.routeFiles {
		out[path] = src
	}
	for path, src := range renderContentBodies(res.collections) {
		out[path] = src
	}
	out[classesFilePath(root)] = classesBytes(collectClasses(dirs, l, res.pkgs))
	out[galleryFilePath(root)] = renderGallery(root, dirs, l, res.pkgs)
	if len(diags) > 0 {
		sortDiags(diags)
		return nil, diags, res, l, dirs
	}
	return out, nil, res, l, dirs
}

// Stale returns GX1002 for every .gx file whose generated file is missing or
// out of date (REQ-AUT-18).
func Stale(root string) []Diagnostic {
	files, diags := Generate(root)
	if len(diags) > 0 {
		// The check reports most of these too. The generator alone finds a
		// value that cannot render (GX2013), so they are not dropped.
		return diags
	}
	return staleFiles(files)
}

// staleFiles returns GX1002 for each generated file that differs from the
// file on the disk.
func staleFiles(files map[string][]byte) []Diagnostic {
	paths := make([]string, 0, len(files))
	for path := range files {
		paths = append(paths, path)
	}
	sort.Strings(paths)
	var out []Diagnostic
	for _, path := range paths {
		if !strings.HasSuffix(path, "_gx.go") {
			continue
		}
		if onDisk, err := os.ReadFile(path); err == nil && bytes.Equal(onDisk, files[path]) {
			continue
		}
		// A component file names its .gx source. A route file, the content
		// renderer and the gallery have no .gx source, so they name the
		// generated file.
		source := strings.TrimSuffix(path, "_gx.go") + ".gx"
		if _, err := os.Stat(source); err != nil {
			source = path
		}
		out = append(out, Diagnostic{
			Code: CodeStale,
			File: source,
			Line: 1,
			Col:  1,
			Msg:  "generated code is missing or stale; run gx generate",
		})
	}
	return out
}

type gen struct {
	l     *loader
	res   *typesResult
	pkg   *Package
	file  *File
	name  string
	b     bytes.Buffer
	ind   int
	nest  int
	diags []Diagnostic

	// extra holds the imports that a prop default of another package
	// needs at a call site: qualifier to import path.
	extra map[string]string

	// scoped reports whether this component carries a signal instance
	// key (REQ-ACT-06).
	scoped bool
	// rootEl is the first top-level element, which carries data-signals.
	rootEl *Element
	// inFragment and fragKey give the instance key inside a fragment.
	inFragment bool
	fragKey    string
	// keyStack holds the key expressions of enclosing keyed elements.
	keyStack []string
}

// firstTopLevelElement returns the first element of a component body.
func firstTopLevelElement(ns []Node) *Element {
	for _, n := range ns {
		el, ok := n.(*Element)
		if !ok {
			continue
		}
		// A component tag such as <gx.Head> renders through its own
		// function and drops attributes it does not declare.
		if _, _, component := componentTag(el.Name); component {
			continue
		}
		return el
	}
	return nil
}

// hasProp reports whether the props block declares a field.
func hasProp(f *File, name string) bool {
	for _, p := range f.Props {
		if p.Name == name {
			return true
		}
	}
	return false
}

// posOf returns the .gx position of a probe site, or a zero Pos.
func posOf(n any) Pos {
	if p, ok := n.(interface{ Position() Pos }); ok {
		return p.Position()
	}
	return Pos{}
}

func generateFile(l *loader, p *Package, name string, f *File, res *typesResult) ([]byte, []Diagnostic) {
	g := &gen{l: l, res: res, pkg: p, file: f, name: name}
	if comp, ok := p.component(name); ok {
		g.scoped = res.componentScoped(l, p, f, comp, map[*File]bool{})
	}
	g.rootEl = firstTopLevelElement(f.Body)
	g.write("// Code generated by gx. DO NOT EDIT.")
	g.write("")
	g.write("package %s", f.Package)
	g.write("")
	g.write("import (")
	g.ind++
	g.write("gx \"github.com/alternayte/gx\"")
	for _, im := range f.Imports {
		if importPath(im.Raw) == "github.com/alternayte/gx" {
			continue
		}
		g.write("%s", im.Raw)
	}
	g.write("%s", extraImportsMark)
	g.ind--
	g.write(")")
	g.write("")
	g.write("type %sProps struct {", name)
	g.ind++
	for _, fld := range f.Props {
		for _, line := range docLines(fld.Doc) {
			g.write("%s", strings.TrimRight("// "+line, " "))
		}
		g.write("%s %s", fld.Name, fld.Type)
	}
	if g.scoped && !hasProp(f, "GxKey") {
		// GxKey carries the instance key from the call site
		// (REQ-ACT-06). The compiler fills it; it is not written in
		// the props block.
		g.write("GxKey gx.Key")
	}
	g.ind--
	g.write("}")
	g.emitFormSetter(f, name)
	if len(f.Signals) > 0 {
		g.write("")
		g.write("type %sSignals struct {", name)
		g.ind++
		for _, fld := range f.Signals {
			// The JSON tag matches the signal name the client sees
			// (REQ-ACT-05).
			for _, line := range docLines(fld.Doc) {
				g.write("%s", strings.TrimRight("// "+line, " "))
			}
			g.write("%s %s `json:%s`", fld.Name, fld.Type, strconv.Quote(lowerFirst(fld.Name)))
		}
		g.ind--
		g.write("}")
	}
	g.write("")
	g.write("func %s(p %sProps) gx.Node {", name, name)
	g.ind++
	g.write("var _b gx.Builder")
	g.emitStmts(f.Body, "_b")
	g.write("return _b.Node()")
	g.ind--
	g.write("}")
	for _, el := range fragmentElements(f.Body) {
		g.write("")
		g.fragmentFunc(el)
	}
	src, err := fixImports(name+"_gx.go", g.withExtraImports())
	if err != nil {
		return nil, append(g.diags, Diagnostic{
			Code: CodeParse,
			File: f.File,
			Line: 1,
			Col:  1,
			Msg:  "cannot format generated code: " + err.Error(),
		})
	}
	return src, g.diags
}

// emitFormSetter writes the GxSetForm method of a view props struct when a
// prop holds a generated form value (REQ-FRM-03).
func (g *gen) emitFormSetter(f *File, name string) {
	pt := g.res.propTypes[f]
	if pt == nil || g.res.formIface == nil {
		return
	}
	for i, fld := range f.Props {
		if i >= len(pt) || pt[i] == nil || !types.Implements(pt[i], g.res.formIface) {
			continue
		}
		g.write("")
		g.write("// GxSetForm fills the form value prop %s (REQ-FRM-03).", fld.Name)
		g.write("func (p *%sProps) GxSetForm(v gx.FormValue) {", name)
		g.ind++
		g.write("p.%s = v.(%s)", fld.Name, fld.Type)
		g.ind--
		g.write("}")
		return
	}
}

func (g *gen) write(format string, args ...any) {
	if format != "" {
		g.b.WriteString(strings.Repeat("\t", g.ind))
		fmt.Fprintf(&g.b, format, args...)
	}
	g.b.WriteByte('\n')
}

func (g *gen) newBuilder() string {
	g.nest++
	return fmt.Sprintf("_b%d", g.nest)
}

func (g *gen) fail(n any, code, context string, format string, args ...any) {
	at := posOf(n)
	g.diags = append(g.diags, Diagnostic{
		Code: code,
		File: g.file.File,
		Line: at.Line,
		Col:  at.Col,
		Msg:  context + ": " + fmt.Sprintf(format, args...),
	})
}

func (g *gen) errorf(n any, context string, format string, args ...any) {
	g.fail(n, CodeUnrenderable, context, format, args...)
}

// classCondition returns the bool expression of a class:<name> attribute.
func (g *gen) classCondition(a *Attr) string {
	expr := strings.TrimSpace(a.Value)
	if strings.Contains(expr, "$") {
		g.fail(a, CodeSignal, "attribute "+strconv.Quote(a.Name), "a signal is only valid in a client expression")
		return ""
	}
	if g.isBoolType(a) {
		return expr
	}
	g.fail(a, CodeType, "attribute "+strconv.Quote(a.Name), "needs a bool expression")
	return ""
}

func (g *gen) add(builder, expr string) {
	g.write("%s.Add(%s)", builder, expr)
}

// lineAt emits a //line directive so that Go tooling and stack traces report
// .gx positions (REQ-TLS-02).
func (g *gen) lineAt(n Node) {
	at := posOf(n)
	if at.Line <= 0 {
		return
	}
	// A //line directive is only honored at column 1.
	g.b.WriteString(fmt.Sprintf("//line %s:%d:%d\n", filepath.Base(g.file.File), at.Line, at.Col))
}

// subtreeNeedsBlock reports whether ns holds a statement (a let or a control)
// anywhere below it.
func subtreeNeedsBlock(ns []Node) bool {
	for _, n := range ns {
		switch t := n.(type) {
		case *Let, *Control:
			return true
		case *Element:
			if subtreeNeedsBlock(t.Children) {
				return true
			}
		}
	}
	return false
}

func (g *gen) emitStmts(ns []Node, builder string) {
	for _, n := range ns {
		switch t := n.(type) {
		case *Text:
			g.lineAt(t)
			g.add(builder, "gx.Text("+strconv.Quote(t.Data)+")")
		case *HTMLComment:
			g.lineAt(t)
			g.add(builder, "gx.Raw(gx.SafeHTML("+strconv.Quote("<!--"+t.Data+"-->")+"))")
		case *Comment:
			// A {/* ... */} comment never renders (REQ-AUT-16).
		case *Expr:
			g.lineAt(t)
			g.add(builder, g.exprValue(t, t.Data))
		case *Let:
			g.lineAt(t)
			g.write("%s := %s", t.Name, t.Expr)
		case *Control:
			g.emitControl(t, builder)
		case *Element:
			g.lineAt(t)
			pushed := g.keyAttrExpr(t)
			if pushed != "" {
				g.keyStack = append(g.keyStack, pushed)
			}
			if qual, name, ok := componentTag(t.Name); ok {
				g.emitComponent(t, qual, name, builder)
			} else if subtreeNeedsBlock(t.Children) {
				nb := g.newBuilder()
				g.write("var %s gx.Builder", nb)
				g.emitStmts(t.Children, nb)
				g.add(builder, g.elementExprWith(t, nb+".Node()"))
			} else {
				g.add(builder, g.elementExpr(t))
			}
			if pushed != "" {
				g.keyStack = g.keyStack[:len(g.keyStack)-1]
			}
		}
	}
}

func (g *gen) emitControl(c *Control, builder string) {
	g.lineAt(c)
	switch c.Kind {
	case "if":
		header := strings.TrimSpace(c.Header)
		if header == "" {
			header = "true"
		}
		g.write("if %s {", header)
		g.ind++
		g.emitStmts(c.Body, builder)
		g.ind--
		if len(c.Else) > 0 {
			g.write("} else {")
			g.ind++
			g.emitStmts(c.Else, builder)
			g.ind--
		}
		g.write("}")
	case "for":
		header := strings.TrimSpace(c.Header)
		if header == "" {
			g.write("for {")
		} else {
			g.write("for %s {", header)
		}
		g.ind++
		g.emitStmts(c.Body, builder)
		g.ind--
		g.write("}")
	case "switch":
		header := strings.TrimSpace(c.Header)
		if header == "" {
			g.write("switch {")
		} else {
			g.write("switch %s {", header)
		}
		g.ind++
		for _, cs := range c.Cases {
			if cs.IsDefault {
				g.write("default:")
			} else {
				g.write("case %s:", cs.Header)
			}
			g.ind++
			g.emitStmts(cs.Body, builder)
			g.ind--
		}
		g.ind--
		g.write("}")
	}
}

// exprValue returns the gx.Node expression for a text expression.
func (g *gen) exprValue(n any, raw string) string {
	expr := strings.TrimSpace(raw)
	if expr == "" || strings.Contains(expr, "$") {
		if strings.Contains(expr, "$") {
			g.errorf(n, "expression "+strconv.Quote(expr), "a signal is only valid in a client expression")
		}
		return "gx.Text(\"\")"
	}
	if lit, ok := g.res.codeFiles[n]; ok {
		return lit
	}
	t := g.res.types[n]
	switch {
	case t == nil:
		g.errorf(n, "expression "+strconv.Quote(expr), "cannot determine the type")
		return "gx.Text(\"\")"
	case t.String() == "string":
		return "gx.Text(" + expr + ")"
	case g.res.isNode(t):
		return expr
	case t.String() == "github.com/alternayte/gx.SafeHTML":
		return "gx.Raw(" + expr + ")"
	case isSecretType(t):
		// A conversion gives the secret in clear. String gives the
		// redacted form (SI-04).
		return "gx.Text((" + expr + ").String())"
	case isNamedUnderlying(t, types.String):
		return "gx.Text(string(" + expr + "))"
	case g.res.renderable(t):
		return "gx.Value(" + expr + ")"
	default:
		g.errorf(n, "expression "+strconv.Quote(expr), "cannot render a value of type %s", t.String())
		return "gx.Text(\"\")"
	}
}

func (g *gen) elementExpr(el *Element) string {
	if el.HasRaw {
		// The contents of script and style are raw (REQ-AUT-03). They are
		// a constant of the template, so the conversion is safe.
		if el.RawText == "" {
			return g.elementCall(el, "")
		}
		return g.elementCall(el, "gx.Raw(gx.SafeHTML("+strconv.Quote(el.RawText)+"))")
	}
	return g.elementCall(el, g.childExprs(el.Children))
}

func (g *gen) elementExprWith(el *Element, childrenExpr string) string {
	return g.elementCall(el, childrenExpr)
}

func (g *gen) elementCall(el *Element, childrenExpr string) string {
	attrs := g.attrsExpr(el)
	if childrenExpr == "" {
		return fmt.Sprintf("gx.El(%s, %s)", strconv.Quote(el.Name), attrs)
	}
	return fmt.Sprintf("gx.El(%s, %s, %s)", strconv.Quote(el.Name), attrs, childrenExpr)
}

// childExprs returns the children of an element as one gx.Node expression.
func (g *gen) childExprs(ns []Node) string {
	var parts []string
	for _, n := range ns {
		switch t := n.(type) {
		case *Text:
			parts = append(parts, "gx.Text("+strconv.Quote(t.Data)+")")
		case *HTMLComment:
			parts = append(parts, "gx.Raw(gx.SafeHTML("+strconv.Quote("<!--"+t.Data+"-->")+"))")
		case *Comment:
		case *Expr:
			parts = append(parts, g.exprValue(t, t.Data))
		case *Element:
			pushed := g.keyAttrExpr(t)
			if pushed != "" {
				g.keyStack = append(g.keyStack, pushed)
			}
			if qual, name, ok := componentTag(t.Name); ok {
				parts = append(parts, g.componentCallExpr(t, qual, name, nil))
			} else {
				parts = append(parts, g.elementExpr(t))
			}
			if pushed != "" {
				g.keyStack = g.keyStack[:len(g.keyStack)-1]
			}
		}
	}
	switch len(parts) {
	case 0:
		return ""
	case 1:
		return parts[0]
	default:
		return "gx.Frag(" + strings.Join(parts, ", ") + ")"
	}
}

func (g *gen) attrsExpr(el *Element) string {
	var parts []string
	var static []string
	var classParts []string
	var styleParts []string
	if el == g.rootEl && len(g.file.Signals) > 0 {
		static = append(static, g.signalsAttrs()...)
	}
	spread := false
	flush := func() {
		if len(static) == 0 {
			return
		}
		parts = append(parts, "gx.Attrs{"+strings.Join(static, ", ")+"}")
		static = nil
	}
	activeMode := ""
	for i := range el.Attrs {
		if el.Attrs[i].Kind == AttrString && el.Attrs[i].Name == "active" {
			activeMode = el.Attrs[i].Value
			break
		}
	}
	for i := range el.Attrs {
		a := &el.Attrs[i]
		if a.Kind == AttrString && a.Name == "active" {
			continue // a gx directive, not an HTML attribute
		}
		// The class attribute and the class:<name> directives join in
		// source order (REQ-AUT-10).
		switch a.Kind {
		case AttrString:
			if a.Name == "class" {
				classParts = append(classParts, strconv.Quote(a.Value))
				continue
			}
			if a.Name == "style" {
				styleParts = append(styleParts, "gx.Style("+strconv.Quote(a.Value)+")")
				continue
			}
		case AttrBool:
			if rest, ok := strings.CutPrefix(a.Name, "class:"); ok {
				classParts = append(classParts, strconv.Quote(rest))
				continue
			}
		case AttrExpr:
			if rest, ok := strings.CutPrefix(a.Name, "class:"); ok {
				if strings.Contains(a.Value, "$") {
					if site := g.res.clientBy[a]; site != nil {
						if v, ok := g.clientAttrValue(a, site); ok {
							static = append(static, fmt.Sprintf("gx.Attr{Key: %s, Value: %s, Kind: gx.AttrText}",
								strconv.Quote("data-class:"+rest), v))
						}
					}
					continue
				}
				if cond := g.classCondition(a); cond != "" {
					classParts = append(classParts, fmt.Sprintf("gx.When(%s, %s)", strconv.Quote(rest), cond))
				}
				continue
			}
			if a.Name == "class" {
				if v, ok := g.attrValueExpr(a, a.Value); ok {
					classParts = append(classParts, v)
				}
				continue
			}
		}
		switch a.Kind {
		case AttrSpread:
			spread = true
			flush()
			parts = append(parts, strings.TrimSpace(a.Value))
		case AttrString:
			kind := "gx.AttrText"
			if isURLAttr(a.Name) {
				kind = "gx.AttrURL"
			}
			static = append(static, fmt.Sprintf("gx.Attr{Key: %s, Value: %s, Kind: %s}",
				strconv.Quote(a.Name), strconv.Quote(a.Value), kind))
		case AttrBool:
			static = append(static, fmt.Sprintf("gx.Bool(%s, true)", strconv.Quote(a.Name)))
		case AttrExpr:
			target := a.Name
			if rest, ok := strings.CutPrefix(target, "attr:"); ok {
				target = rest
			}
			value := strings.TrimSpace(a.Value)
			if isBoolAttr(target) && g.isBoolType(a) && !strings.Contains(value, "$") {
				static = append(static, fmt.Sprintf("gx.Bool(%s, %s)", strconv.Quote(target), value))
				continue
			}
			if isURLAttr(a.Name) {
				t := g.res.types[a]
				value := ""
				switch {
				case t != nil && t.String() == "github.com/alternayte/gx.URL":
					value = "string(" + strings.TrimSpace(a.Value) + ")"
				case g.res.isURLValue(t):
					value = strings.TrimSpace(a.Value) + ".URL()"
				}
				if value != "" {
					active := `"page"`
					if activeMode == "section" {
						active = `"section"`
					}
					static = append(static, fmt.Sprintf("gx.Attr{Key: %s, Value: %s, Kind: gx.AttrURL, Active: %s}",
						strconv.Quote(a.Name), value, active))
				}
				continue
			}
			if a.Name == "key" {
				if v, ok := g.attrValueExpr(a, a.Value); ok {
					static = append(static, fmt.Sprintf("gx.Attr{Key: \"data-gx-key\", Value: %s, Kind: gx.AttrText}", v))
				}
				continue
			}
			if a.Name == "style" {
				if g.isStyleType(a) {
					styleParts = append(styleParts, "gx.Style("+strings.TrimSpace(a.Value)+")")
				}
				continue
			}
			if a.Name == "transition" {
				if !strings.Contains(a.Value, "$") {
					styleParts = append(styleParts, "gx.TransitionStyle("+strings.TrimSpace(a.Value)+")")
				}
				continue
			}
			if site := g.res.clientBy[a]; site != nil {
				name, ok := g.clientAttrName(a)
				if !ok {
					continue
				}
				if v, ok := g.clientAttrValue(a, site); ok {
					static = append(static, fmt.Sprintf("gx.Attr{Key: %s, Value: %s, Kind: gx.AttrText}",
						strconv.Quote(name), v))
				}
				continue
			}
			if isDirective(a.Name) {
				continue
			}
			value, ok := g.attrValueExpr(a, a.Value)
			if !ok {
				continue
			}
			static = append(static, fmt.Sprintf("gx.Attr{Key: %s, Value: %s, Kind: gx.AttrText}",
				strconv.Quote(a.Name), value))
		}
	}
	if len(styleParts) > 0 {
		styleAttr := fmt.Sprintf("gx.Attr{Key: \"style\", Value: string(gx.StyleJoin(%s)), Kind: gx.AttrStyle}", strings.Join(styleParts, ", "))
		if spread {
			parts = append([]string{"gx.Attrs{" + styleAttr + "}"}, parts...)
		} else {
			static = append([]string{styleAttr}, static...)
		}
	}
	if len(classParts) > 0 {
		classAttr := fmt.Sprintf("gx.Attr{Key: \"class\", Value: %s, Kind: gx.AttrText}", classExpr(classParts))
		if spread {
			parts = append([]string{"gx.Attrs{" + classAttr + "}"}, parts...)
		} else {
			static = append([]string{classAttr}, static...)
		}
	}
	for i := range el.Attrs {
		if el.Attrs[i].Kind != AttrFragment {
			continue
		}
		idAttr := fmt.Sprintf("gx.Attr{Key: \"id\", Value: %s, Kind: gx.AttrText}", g.fragmentID(el, el.Attrs[i].Name))
		if spread {
			parts = append([]string{"gx.Attrs{" + idAttr + "}"}, parts...)
		} else {
			static = append([]string{idAttr}, static...)
		}
		break
	}
	flush()
	switch len(parts) {
	case 0:
		return "nil"
	case 1:
		return parts[0]
	default:
		return "gx.JoinAttrs(" + strings.Join(parts, ", ") + ")"
	}
}

// fragmentFunc generates the function of one #fragment element.
func (g *gen) fragmentFunc(el *Element) {
	var frag *Attr
	for i := range el.Attrs {
		if el.Attrs[i].Kind == AttrFragment {
			frag = &el.Attrs[i]
			break
		}
	}
	if frag == nil {
		return
	}
	name := g.name + upperFirst(frag.Name)
	g.lineAt(el)
	var params []string
	keyParam := ""
	if g.scoped && !declaresKey(fragmentParams(el)) {
		// A fragment in a signal-bearing component takes the instance
		// key first (REQ-ACT-14).
		params = append(params, "key gx.Key")
		keyParam = "key"
	} else if declaresKey(fragmentParams(el)) {
		keyParam = "gx.Key(key)"
	}
	if usesP(el) {
		params = append(params, "p "+g.name+"Props")
	}
	if ps := strings.TrimSpace(frag.Value); ps != "" {
		params = append(params, ps)
	}
	g.write("func %s(%s) gx.Node {", name, strings.Join(params, ", "))
	g.ind++
	savedFrag, savedKey := g.inFragment, g.fragKey
	g.inFragment, g.fragKey = true, keyParam
	g.write("var _b gx.Builder")
	g.emitStmts([]Node{el}, "_b")
	g.write("return _b.Node()")
	g.inFragment, g.fragKey = savedFrag, savedKey
	g.ind--
	g.write("}")
}

// usesP reports whether the subtree reads the props value p.
func usesP(el *Element) bool {
	found := false
	visitExprs([]Node{el}, func(expr string) {
		if hasIdent(expr, "p") {
			found = true
		}
	})
	return found
}

// visitExprs calls fn for every expression text in ns.
func visitExprs(ns []Node, fn func(string)) {
	for _, n := range ns {
		switch t := n.(type) {
		case *Expr:
			fn(t.Data)
		case *Let:
			fn(t.Expr)
		case *Control:
			fn(t.Header)
			visitExprs(t.Body, fn)
			visitExprs(t.Else, fn)
			for _, c := range t.Cases {
				fn(c.Header)
				visitExprs(c.Body, fn)
			}
		case *Element:
			for i := range t.Attrs {
				if t.Attrs[i].Kind == AttrExpr {
					fn(t.Attrs[i].Value)
				}
			}
			visitExprs(t.Children, fn)
		}
	}
}

// hasIdent reports whether s holds ident as a whole identifier.
func hasIdent(s, ident string) bool {
	for i := 0; i+len(ident) <= len(s); i++ {
		if s[i:i+len(ident)] != ident {
			continue
		}
		before := i == 0 || !isIdentByte(s[i-1])
		after := i+len(ident) == len(s) || !isIdentByte(s[i+len(ident)])
		if before && after {
			return true
		}
	}
	return false
}

func isIdentByte(c byte) bool {
	return c == '_' || isLetter(c) || isDigit(c)
}

// classExpr returns the Go expression of a class value.
func classExpr(parts []string) string {
	if len(parts) == 1 {
		return parts[0]
	}
	return "gx.Classes(" + strings.Join(parts, ", ") + ")"
}

func (g *gen) attrValueExpr(n any, raw string) (string, bool) {
	expr := strings.TrimSpace(raw)
	if strings.Contains(expr, "$") {
		g.errorf(n, "attribute "+strconv.Quote(expr), "a signal is only valid in a client expression")
		return "", false
	}
	t := g.res.types[n]
	switch {
	case t == nil:
		g.errorf(n, "attribute "+strconv.Quote(expr), "cannot determine the type")
		return "", false
	case t.String() == "string":
		return expr, true
	case isSecretType(t):
		return "(" + expr + ").String()", true
	case isNamedUnderlying(t, types.String):
		return "string(" + expr + ")", true
	case g.res.renderable(t):
		return "gx.TextValue(" + expr + ")", true
	default:
		g.errorf(n, "attribute "+strconv.Quote(expr), "cannot render a value of type %s", t.String())
		return "", false
	}
}

// childPart is the default slot ("children") or one named slot of a component
// call.
type childPart struct {
	key   string
	slot  *Element
	nodes []Node
}

func splitChildren(ns []Node) []childPart {
	var parts []childPart
	index := map[string]int{}
	add := func(key string, nodes []Node, slot *Element, exists bool) {
		if i, ok := index[key]; ok {
			parts[i].nodes = append(parts[i].nodes, nodes...)
			return
		}
		if !exists {
			return
		}
		index[key] = len(parts)
		parts = append(parts, childPart{key: key, slot: slot, nodes: nodes})
	}
	for _, n := range ns {
		if el, ok := n.(*Element); ok && strings.HasPrefix(el.Name, ":") {
			add(strings.TrimPrefix(el.Name, ":"), el.Children, el, true)
			continue
		}
		if t, ok := n.(*Text); ok && strings.TrimSpace(t.Data) == "" {
			continue
		}
		add("children", []Node{n}, nil, true)
	}
	return parts
}

func (g *gen) emitComponent(el *Element, qual, name, builder string) {
	comp, _, _ := g.resolveComponent(qual, name)
	built := map[string]string{}
	for _, part := range splitChildren(el.Children) {
		if comp != nil && g.isSlotProp(comp, part) {
			continue // the slot closure carries the statements
		}
		if subtreeNeedsBlock(part.nodes) {
			nb := g.newBuilder()
			g.write("var %s gx.Builder", nb)
			g.emitStmts(part.nodes, nb)
			built[part.key] = nb + ".Node()"
		}
	}
	g.add(builder, g.componentCallExpr(el, qual, name, built))
}

// isSlotProp reports whether the part fills a gx.Slot[T] prop.
func (g *gen) isSlotProp(comp *Component, part childPart) bool {
	propName := "Children"
	if part.key != "children" {
		propName = upperFirst(part.key)
	}
	prop, ok := findProp(comp, lowerFirst(propName))
	if !ok {
		return false
	}
	_, isSlot := slotTypeArg(prop.Type)
	return isSlot
}

// slotClosure returns a func(value T) gx.Node for a gx.Slot[T] prop.
func (g *gen) slotClosure(param, elemType string, ns []Node) string {
	sub := &gen{l: g.l, res: g.res, pkg: g.pkg, file: g.file, name: g.name, ind: 1}
	sub.write("var _c gx.Builder")
	sub.emitStmts(ns, "_c")
	sub.write("return _c.Node()")
	return "func(" + param + " " + elemType + ") gx.Node {\n" + sub.b.String() + "}"
}

// componentCallExpr returns the Go call expression for a component element.
func (g *gen) componentCallExpr(el *Element, qual, name string, built map[string]string) string {
	comp, targetPkg, alias := g.resolveComponent(qual, name)
	if comp == nil {
		return "nil"
	}
	valueFor := map[string]string{}
	for i := range el.Attrs {
		a := &el.Attrs[i]
		if a.Kind == AttrFragment || a.Kind == AttrSpread || isDirective(a.Name) {
			continue
		}
		prop, ok := findProp(comp, a.Name)
		if !ok {
			continue
		}
		switch a.Kind {
		case AttrString:
			valueFor[prop.Name] = strconv.Quote(a.Value)
		case AttrBool:
			valueFor[prop.Name] = "true"
		case AttrExpr:
			if elem, isRef := signalRefArg(prop.Type); isRef {
				if v, ok := g.signalRefValue(a, elem); ok {
					valueFor[prop.Name] = v
				}
				continue
			}
			if lit, ok := g.res.codeFiles[a]; ok {
				valueFor[prop.Name] = lit
				continue
			}
			valueFor[prop.Name] = strings.TrimSpace(a.Value)
		}
	}
	for _, part := range splitChildren(el.Children) {
		propName := "Children"
		if part.key != "children" {
			propName = upperFirst(part.key)
		}
		prop, ok := findProp(comp, lowerFirst(propName))
		if !ok {
			continue
		}
		if elem, isSlot := slotTypeArg(prop.Type); isSlot {
			valueFor[prop.Name] = g.slotClosure(slotLetName(part.slot), elem, part.nodes)
			continue
		}
		expr, ok := built[part.key]
		if !ok {
			expr = g.childExprs(part.nodes)
		}
		if expr == "" {
			continue
		}
		valueFor[prop.Name] = expr
	}

	if g.res.componentScoped(g.l, targetPkg, comp.File, comp, map[*File]bool{}) {
		if key := g.callKeyExpr(el); key != "" {
			valueFor["GxKey"] = key
		}
	}

	cross := targetPkg != g.pkg
	var fields []string
	for idx, prop := range comp.Props {
		if v, ok := valueFor[prop.Name]; ok {
			fields = append(fields, prop.Name+": "+v)
			continue
		}
		if !prop.HasDefault {
			continue // the checker reports the missing prop
		}
		def := prop.Default
		if cross && comp.File != nil {
			if names := g.res.quals[comp.File][idx]; len(names) > 0 {
				def = qualifyDefault(def, names, alias)
			}
			for qual, path := range g.res.qualPkgs[comp.File][idx] {
				if g.extra == nil {
					g.extra = map[string]string{}
				}
				g.extra[qual] = path
			}
		}
		fields = append(fields, prop.Name+": "+def)
	}
	if v, ok := valueFor["GxKey"]; ok && !hasProp(comp.File, "GxKey") {
		fields = append(fields, "GxKey: "+v)
	}
	sel := ""
	if alias != "" {
		sel = alias + "."
	}
	props := sel + comp.Name + "Props{" + strings.Join(fields, ", ") + "}"
	return sel + comp.Name + "(" + props + ")"
}

// extraImportsMark holds the place of the imports that a call site adds
// after the import block is written.
const extraImportsMark = "//gx:extra-imports"

// withExtraImports returns the generated source with the imports of the
// prop defaults of other packages. An import the file already has is not
// added twice.
func (g *gen) withExtraImports() []byte {
	have := map[string]bool{"github.com/alternayte/gx": true}
	for _, im := range g.file.Imports {
		have[importPath(im.Raw)] = true
	}
	quals := make([]string, 0, len(g.extra))
	for qual, path := range g.extra {
		if !have[path] {
			quals = append(quals, qual)
		}
	}
	sort.Strings(quals)
	var lines []string
	for _, qual := range quals {
		lines = append(lines, qual+" "+strconv.Quote(g.extra[qual]))
	}
	return bytes.Replace(g.b.Bytes(), []byte(extraImportsMark), []byte(strings.Join(lines, "\n")), 1)
}

func (g *gen) resolveComponent(qual, name string) (*Component, *Package, string) {
	return resolveComponent(g.l, g.pkg, g.file, qual, name)
}

// qualifyDefault rewrites package-owned identifiers of a default expression to
// the qualifier used at the call site.
func qualifyDefault(src string, names map[string]bool, alias string) string {
	expr, err := goparser.ParseExpr(src)
	if err != nil {
		return src
	}
	rewriteQualified(expr, names, alias)
	var b bytes.Buffer
	goprinter.Fprint(&b, token.NewFileSet(), expr)
	return b.String()
}

func rewriteQualified(expr ast.Expr, names map[string]bool, alias string) {
	switch e := expr.(type) {
	case *ast.Ident:
		if names[e.Name] {
			e.Name = alias + "." + e.Name
		}
	case *ast.SelectorExpr:
		rewriteQualified(e.X, names, alias)
	case *ast.ParenExpr:
		rewriteQualified(e.X, names, alias)
	case *ast.StarExpr:
		rewriteQualified(e.X, names, alias)
	case *ast.UnaryExpr:
		rewriteQualified(e.X, names, alias)
	case *ast.BinaryExpr:
		rewriteQualified(e.X, names, alias)
		rewriteQualified(e.Y, names, alias)
	case *ast.CallExpr:
		rewriteQualified(e.Fun, names, alias)
		for _, a := range e.Args {
			rewriteQualified(a, names, alias)
		}
	case *ast.IndexExpr:
		rewriteQualified(e.X, names, alias)
		rewriteQualified(e.Index, names, alias)
	case *ast.IndexListExpr:
		rewriteQualified(e.X, names, alias)
		for _, i := range e.Indices {
			rewriteQualified(i, names, alias)
		}
	case *ast.CompositeLit:
		if e.Type != nil {
			rewriteQualified(e.Type, names, alias)
		}
		for _, elt := range e.Elts {
			if kv, ok := elt.(*ast.KeyValueExpr); ok {
				rewriteQualified(kv.Value, names, alias)
				continue
			}
			if v, ok := elt.(ast.Expr); ok {
				rewriteQualified(v, names, alias)
			}
		}
	case *ast.ArrayType:
		if e.Elt != nil {
			rewriteQualified(e.Elt, names, alias)
		}
	case *ast.MapType:
		rewriteQualified(e.Key, names, alias)
		rewriteQualified(e.Value, names, alias)
	case *ast.TypeAssertExpr:
		rewriteQualified(e.X, names, alias)
	case *ast.SliceExpr:
		rewriteQualified(e.X, names, alias)
	}
}

func isNamedUnderlying(t types.Type, kind types.BasicKind) bool {
	if _, ok := t.(*types.Named); !ok {
		return false
	}
	b, ok := t.Underlying().(*types.Basic)
	return ok && b.Kind() == kind
}

func (g *gen) isBoolType(n any) bool {
	t := g.res.types[n]
	return t != nil && t.String() == "bool"
}

func (g *gen) isStyleType(n any) bool {
	t := g.res.types[n]
	return t != nil && t.String() == "github.com/alternayte/gx.Style"
}

// clientAttrName returns the adapter attribute name of a client directive
// (REQ-ACT-08).
func (g *gen) clientAttrName(a *Attr) (string, bool) {
	name, err := adapterAttrName(a.Name)
	if err != nil {
		g.fail(a, CodeEventMod, "event modifier", "%s", err)
		return "", false
	}
	return name, true
}

// clientAttrValue returns the Go expression of the adapter attribute of one
// client expression (REQ-ACT-07).
func (g *gen) clientAttrValue(a *Attr, site *clientSite) (string, bool) {
	t := &transpiler{
		res:       g.res,
		file:      g.file,
		scopeBase: g.file.Package + "." + g.name,
		keyExpr:   g.keyExpr(),
		scoped:    g.scoped,
	}
	if site.block {
		block, ok := site.node.(*ast.BlockStmt)
		if !ok {
			return "", false
		}
		v, err := t.transpileStatements(block)
		if err != nil {
			g.fail(a, CodeClientType, "client expression", "%s", err)
			return "", false
		}
		return v, true
	}
	expr, ok := site.node.(ast.Expr)
	if !ok {
		return "", false
	}
	if strings.HasPrefix(a.Name, "bind:") {
		// data-bind takes the dotted signal name, not an expression.
		id, ok := expr.(*ast.Ident)
		if !ok {
			return "", false
		}
		name, ok := strings.CutPrefix(id.Name, "_gxSig_")
		if !ok {
			return "", false
		}
		return "gx.SignalName(" + strconv.Quote(g.file.Package+"."+g.name) + ", " + g.keyExpr() + ", " + strconv.Quote(lowerFirst(name)) + ")", true
	}
	if key := namedTypeKey(g.res.exprTypes[expr]); key != "" && g.res.routeKeys[key] {
		v, err := t.actionValue(expr, key)
		if err != nil {
			g.fail(a, CodeClientType, "client expression", "%s", err)
			return "", false
		}
		return v, true
	}
	v, err := t.transpileValue(expr)
	if err != nil {
		g.fail(a, CodeClientType, "client expression", "%s", err)
		return "", false
	}
	return v, true
}

// keyExpr returns the instance key of the component or fragment that is
// being generated, as a Go expression (REQ-ACT-06).
func (g *gen) keyExpr() string {
	if g.inFragment && g.fragKey != "" {
		return g.fragKey
	}
	if g.scoped {
		return "p.GxKey"
	}
	return ""
}

// parentKeyExpr returns the instance key of the enclosing call site.
func (g *gen) parentKeyExpr() string {
	if n := len(g.keyStack); n > 0 {
		return g.keyStack[n-1]
	}
	if g.inFragment && g.fragKey != "" {
		return g.fragKey
	}
	if g.scoped {
		return "p.GxKey"
	}
	return ""
}

// keyAttrExpr returns the Go expression of a key={expr} attribute, or "".
func (g *gen) keyAttrExpr(el *Element) string {
	for i := range el.Attrs {
		a := &el.Attrs[i]
		if a.Kind == AttrExpr && a.Name == "key" {
			return "gx.InstanceKey(" + strings.TrimSpace(a.Value) + ")"
		}
	}
	return ""
}

// keyAttrValue returns the key expression of an element as Go source, or
// "". A static key string becomes a quoted literal.
func (g *gen) keyAttrValue(el *Element) string {
	for i := range el.Attrs {
		a := &el.Attrs[i]
		if a.Name != "key" {
			continue
		}
		if a.Kind == AttrExpr {
			return strings.TrimSpace(a.Value)
		}
		if a.Kind == AttrString {
			return strconv.Quote(a.Value)
		}
	}
	return ""
}

// signalRefValue returns the Go expression of a gx.SignalRef prop value
// (REQ-ACT-07). The caller names its own signal or passes a parent ref on.
func (g *gen) signalRefValue(a *Attr, elem string) (string, bool) {
	src := strings.TrimSpace(a.Value)
	if name, ok := strings.CutPrefix(src, "$"); ok && isIdent(name) {
		return "gx.Ref[" + elem + "](gx.SignalRefPath(" + strconv.Quote(g.file.Package+"."+g.name) + ", " + g.keyExpr() + ", " + strconv.Quote(lowerFirst(name)) + "))", true
	}
	if name, ok := strings.CutPrefix(src, "p."); ok && isIdent(name) {
		return "gx.Ref[" + elem + "](string(p." + name + "))", true
	}
	g.fail(a, CodeClientType, "signal ref", "a signal ref prop takes $Signal or a parent signal ref")
	return "", false
}

// isIdent reports whether s is a Go identifier.
func isIdent(s string) bool {
	if s == "" || !isLetter(s[0]) && s[0] != '_' {
		return false
	}
	for i := 1; i < len(s); i++ {
		if !isIdentByte(s[i]) {
			return false
		}
	}
	return true
}

// callKeyExpr returns the instance key a scoped component call passes
// (REQ-ACT-06).
func (g *gen) callKeyExpr(el *Element) string {
	if own := g.keyAttrValue(el); own != "" {
		return "gx.InstanceKey(" + own + ")"
	}
	site := el.At.Line*1000 + el.At.Col
	if parent := g.parentKeyExpr(); parent != "" {
		return fmt.Sprintf("gx.ChildKey(%s, %d)", parent, site)
	}
	return fmt.Sprintf("gx.ChildKey(\"\", %d)", site)
}

// fragmentID returns the Go expression of the id of one fragment instance
// (REQ-AUT-13).
func (g *gen) fragmentID(el *Element, name string) string {
	prefix := strconv.Quote(lowerFirst(g.name))
	if own := g.keyAttrValue(el); own != "" {
		return "gx.FragmentID(" + prefix + ", " + strconv.Quote(name) + ", gx.InstanceKey(" + own + "))"
	}
	if key := g.keyExpr(); key != "" {
		return "gx.FragmentID(" + prefix + ", " + strconv.Quote(name) + ", " + key + ")"
	}
	return strconv.Quote(lowerFirst(g.name) + "-" + name)
}

// signalsAttrs returns the data-signals and instance attributes of the
// component root (REQ-ACT-05, REQ-ACT-06).
func (g *gen) signalsAttrs() []string {
	base := g.file.Package + "." + g.name
	var entries []string
	for _, s := range g.file.Signals {
		entries = append(entries, strconv.Quote(lowerFirst(s.Name))+": "+s.Default)
	}
	values := "map[string]any{" + strings.Join(entries, ", ") + "}"
	return []string{
		fmt.Sprintf("gx.Attr{Key: \"data-signals\", Value: gx.SignalJSON(%s, p.GxKey, %s), Kind: gx.AttrText}",
			strconv.Quote(base), values),
		fmt.Sprintf("gx.Attr{Key: \"data-gx-instance\", Value: gx.ScopeString(%s, p.GxKey), Kind: gx.AttrText}",
			strconv.Quote(base)),
	}
}

// declaresKey reports whether a fragment parameter list declares a key
// parameter first.
func declaresKey(params string) bool {
	parts := splitParams(params)
	return len(parts) > 0 && firstIdent(parts[0]) == "key"
}

// isURLAttr reports whether an attribute holds a URL. A browser reads the
// name in any letter case.
func isURLAttr(name string) bool {
	switch strings.ToLower(name) {
	case "href", "src", "action", "formaction":
		return true
	}
	return false
}

// boolAttrs are the HTML boolean attributes (REQ-AUT-08).
var boolAttrs = map[string]bool{
	"allowfullscreen": true, "async": true, "autofocus": true, "autoplay": true,
	"checked": true, "controls": true, "default": true, "defer": true,
	"disabled": true, "formnovalidate": true, "hidden": true, "inert": true,
	"ismap": true, "itemscope": true, "loop": true, "multiple": true,
	"muted": true, "nomodule": true, "novalidate": true, "open": true,
	"playsinline": true, "readonly": true, "required": true, "reversed": true,
	"selected": true,
}

func isBoolAttr(name string) bool { return boolAttrs[name] }

func upperFirst(s string) string {
	if s == "" {
		return s
	}
	return strings.ToUpper(s[:1]) + s[1:]
}
